entries.commands:
# ===== 静态路由（Junos）=====
configure
set routing-options static route {{dest_net}}/{{prefix_len}} next-hop {{next_hop}}
set routing-options static route 0.0.0.0/0 next-hop {{next_hop}}
! 浮动备份：qualified-next-hop + preference（静态路由默认 preference 为 5）
set routing-options static route {{dest_net}}/{{prefix_len}} preference {{main_preference}}
set routing-options static route {{dest_net}}/{{prefix_len}} qualified-next-hop {{backup_hop}} preference {{preference}}
show | compare
commit and-quit
show route {{dest_net}}/{{prefix_len}}
show route protocol static

# ===== 防火墙过滤器（Junos）=====
configure
set firewall family inet filter {{filter_name}} term ALLOW-INTERNAL from source-address {{src_net}}/{{src_prefix}}
set firewall family inet filter {{filter_name}} term ALLOW-INTERNAL from destination-address {{dst_net}}/{{dst_prefix}}
set firewall family inet filter {{filter_name}} term ALLOW-INTERNAL then accept
set firewall family inet filter {{filter_name}} term DENY-LOG from source-address 0.0.0.0/0
set firewall family inet filter {{filter_name}} term DENY-LOG then count DENY-COUNT
set firewall family inet filter {{filter_name}} term DENY-LOG then discard
set interfaces {{port}} unit 0 family inet filter input {{filter_name}}
show | compare
commit and-quit
show firewall filter {{filter_name}}
show firewall
